 "content": "def transform(grid):
    """Overlay four stacked masks with priority 5 > 4 > 8 > 2."""
    if not grid or len(grid) % 4:
        raise ValueError("expected four equally sized stacked layers")
    h = len(grid) // 4
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid must be rectangular")
    out = [[0] * width for _ in range(h)]
    priority = (5, 4, 8, 2)
    for r in range(h):
        for c in range(width):
            values = [grid[k * h + r][c] for k in range(4)]
            for color in priority:
                if color in values:
                    out[r][c] = color
                    break
    return out
